
window.WeddingPlannerAuthGuard = { ready:false, authenticated:false, uid:'' };
(() => {
  'use strict';

  const DEFAULT_WEDDING_DATE = '2027-01-16';
  const WEDDING_DATE_STORAGE_KEY = 'planificador_bodas_fecha_v1';
  let weddingDateValue = localStorage.getItem(WEDDING_DATE_STORAGE_KEY) || DEFAULT_WEDDING_DATE;
  let WEDDING_DATE = new Date(weddingDateValue + 'T17:00:00-05:00');
  const MODULES = {"checklist":{"title":"Checklist de boda","html":""},"presupuesto":{"title":"Presupuesto","html":""},"proveedores":{"title":"Proveedores","html":""},"invitados":{"title":"Lista de invitados","html":"","previewHtml":""},"distribucion":{"title":"Distribución y diseño","html":""},"cronograma":{"title":"Cronograma","html":""},"invitaciones":{"title":"Invitaciones","html":""},"musica":{"title":"Música","html":""}};

  const body = document.body;
  const menuButton = document.getElementById('menuButton');
  const weddingDateLabel = document.getElementById('weddingDateLabel');
  const editWeddingDateButton = document.getElementById('editWeddingDateButton');
  const dateEditor = document.getElementById('dateEditor');
  const weddingDateInput = document.getElementById('weddingDateInput');
  const saveWeddingDateButton = document.getElementById('saveWeddingDateButton');
  const cancelWeddingDateButton = document.getElementById('cancelWeddingDateButton');

  function formatWeddingDate(value) {
    const parts = String(value || DEFAULT_WEDDING_DATE).split('-');
    return parts.length === 3 ? `${parts[2]}.${parts[1]}.${parts[0]}` : '16.01.2027';
  }

  function applyWeddingDate(value, persist = true) {
    weddingDateValue = /^\d{4}-\d{2}-\d{2}$/.test(String(value || '')) ? value : DEFAULT_WEDDING_DATE;
    WEDDING_DATE = new Date(weddingDateValue + 'T17:00:00-05:00');
    weddingDateLabel.textContent = formatWeddingDate(weddingDateValue);
    weddingDateInput.value = weddingDateValue;
    if (persist) localStorage.setItem(WEDDING_DATE_STORAGE_KEY, weddingDateValue);
    updateCountdown();
  }

  editWeddingDateButton.addEventListener('click', () => {
    weddingDateInput.value = weddingDateValue;
    dateEditor.classList.add('show');
    weddingDateInput.focus();
  });
  cancelWeddingDateButton.addEventListener('click', () => dateEditor.classList.remove('show'));
  saveWeddingDateButton.addEventListener('click', () => {
    if (!weddingDateInput.value) return;
    applyWeddingDate(weddingDateInput.value, true);
    dateEditor.classList.remove('show');
    showToast('Fecha de la boda actualizada.');
    window.dispatchEvent(new Event('migrandia:datachange'));
  });
  applyWeddingDate(weddingDateValue, false);
  const drawer = document.getElementById('mainDrawer');
  const backdrop = document.getElementById('backdrop');
  const toast = document.getElementById('toast');
  const modules = document.querySelectorAll('.module');
  const workspace = document.getElementById('unifiedWorkspace');
  const moduleQuickHome = document.getElementById('moduleQuickHome');
  const moduleQuickTabs = [
    ...document.querySelectorAll('[data-quick-module]')
  ];
  const homeButton = document.getElementById('unifiedHomeButton');
  const loader = document.getElementById('unifiedLoader');
  const loaderText = document.getElementById('unifiedLoaderText');
  const heroVideo = document.getElementById('heroVideo');
  const videoRecovery = document.getElementById('videoRecovery');
  const heroVideoInput = document.getElementById('heroVideoInput');
  const selectHeroVideoButton = document.getElementById('selectHeroVideoButton');
  const hideVideoRecoveryButton = document.getElementById('hideVideoRecoveryButton');

  const frames = new Map();
  let toastTimer;

  const GENERAL_BACKUP_TYPE =
    'planificador_bodas_respaldo_general';

  const GENERAL_BACKUP_VERSION = 1;

  const GENERAL_SAVE_KEY =
    'planificador_bodas_guardado_general_v1';

  let generalBackupBusy = false;


  const VIDEO_DB_NAME = 'planificador_bodas_portada_v1';
  const VIDEO_STORE_NAME = 'assets';
  const VIDEO_KEY = 'heroVideo';
  let currentHeroVideoUrl = '';

  function openVideoDatabase() {
    return new Promise((resolve, reject) => {
      const request = indexedDB.open(VIDEO_DB_NAME, 1);

      request.onupgradeneeded = () => {
        const database = request.result;

        if (!database.objectStoreNames.contains(VIDEO_STORE_NAME)) {
          database.createObjectStore(VIDEO_STORE_NAME);
        }
      };

      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    });
  }

  async function readStoredVideo() {
    const database = await openVideoDatabase();

    return new Promise((resolve, reject) => {
      const transaction = database.transaction(
        VIDEO_STORE_NAME,
        'readonly'
      );

      const store = transaction.objectStore(VIDEO_STORE_NAME);
      const request = store.get(VIDEO_KEY);

      request.onsuccess = () => resolve(request.result || null);
      request.onerror = () => reject(request.error);
      transaction.oncomplete = () => database.close();
    });
  }

  async function saveStoredVideo(file) {
    const database = await openVideoDatabase();

    return new Promise((resolve, reject) => {
      const transaction = database.transaction(
        VIDEO_STORE_NAME,
        'readwrite'
      );

      transaction
        .objectStore(VIDEO_STORE_NAME)
        .put(file, VIDEO_KEY);

      transaction.oncomplete = () => {
        database.close();
        resolve();
      };

      transaction.onerror = () => {
        database.close();
        reject(transaction.error);
      };
    });
  }

  function useHeroVideoBlob(blob) {
    if (currentHeroVideoUrl) {
      URL.revokeObjectURL(currentHeroVideoUrl);
    }

    currentHeroVideoUrl = URL.createObjectURL(blob);
    heroVideo.src = currentHeroVideoUrl;
    heroVideo.load();

    const playPromise = heroVideo.play();

    if (playPromise && typeof playPromise.catch === 'function') {
      playPromise.catch(() => {});
    }

    videoRecovery.classList.remove('show');
  }

  async function initializeHeroVideo() {
    try {
      const storedVideo = await readStoredVideo();

      if (storedVideo instanceof Blob && storedVideo.size) {
        useHeroVideoBlob(storedVideo);
        return;
      }
    } catch (error) {
      console.warn('No se pudo leer el video almacenado.', error);
    }

    let loaded = false;

    const markLoaded = () => {
      loaded = true;
      videoRecovery.classList.remove('show');
    };

    heroVideo.addEventListener('loadeddata', markLoaded, { once: true });

    window.setTimeout(() => {
      if (!loaded && heroVideo.readyState < 2) {
        videoRecovery.classList.add('show');
      }
    }, 1400);
  }

  selectHeroVideoButton.addEventListener('click', () => {
    heroVideoInput.click();
  });

  hideVideoRecoveryButton.addEventListener('click', () => {
    videoRecovery.classList.remove('show');
  });

  heroVideoInput.addEventListener('change', async (event) => {
    const file = event.target.files && event.target.files[0];

    if (!file) {
      return;
    }

    if (!file.type.startsWith('video/')) {
      showToast('Selecciona un archivo de video válido.');
      return;
    }

    useHeroVideoBlob(file);

    try {
      await saveStoredVideo(file);
      showToast('Video de portada guardado en este navegador.');
    } catch (error) {
      console.error(error);
      showToast('El video funciona, pero no pudo guardarse en el navegador.');
    }

    heroVideoInput.value = '';
  });


  const EXTRA_WEDDING_STORAGE_KEYS = new Set([
    'eventPlannerActiveProposalIdV1',
    'eventPlannerLayout',
    'eventPlannerProposalMemoryV1',
    'eventPlannerLatestEmergencyBackupV5'
  ]);

  function isWeddingStorageKey(key) {
    return (
      (key.startsWith('planificador_bodas_') && key !== GENERAL_SAVE_KEY) ||
      EXTRA_WEDDING_STORAGE_KEYS.has(key)
    );
  }

  function collectWeddingLocalStorage() {
    const result = {};

    for (let index = 0; index < localStorage.length; index++) {
      const key = localStorage.key(index);

      if (key && isWeddingStorageKey(key)) {
        result[key] = localStorage.getItem(key);
      }
    }

    return result;
  }

  function clearWeddingLocalStorage() {
    const keys = [];

    for (let index = 0; index < localStorage.length; index++) {
      const key = localStorage.key(index);

      if (key && isWeddingStorageKey(key)) {
        keys.push(key);
      }
    }

    keys.forEach((key) => {
      localStorage.removeItem(key);
    });
  }

  function fileToDataUrl(blob) {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();

      reader.onload = () => resolve(reader.result);
      reader.onerror = () => reject(reader.error);
      reader.readAsDataURL(blob);
    });
  }

  async function serializeBackupValue(value) {
    if (value instanceof Blob) {
      return {
        __weddingType: 'Blob',
        type: value.type || '',
        name:
          typeof File !== 'undefined' &&
          value instanceof File
            ? value.name
            : '',
        lastModified:
          typeof File !== 'undefined' &&
          value instanceof File
            ? value.lastModified
            : 0,
        dataUrl: await fileToDataUrl(value)
      };
    }

    if (value instanceof ArrayBuffer) {
      const bytes = new Uint8Array(value);
      let binary = '';

      bytes.forEach((byte) => {
        binary += String.fromCharCode(byte);
      });

      return {
        __weddingType: 'ArrayBuffer',
        base64: btoa(binary)
      };
    }

    if (ArrayBuffer.isView(value)) {
      const serialized = await serializeBackupValue(
        value.buffer
      );

      return {
        __weddingType: 'TypedArray',
        constructor: value.constructor.name,
        buffer: serialized
      };
    }

    if (value instanceof Date) {
      return {
        __weddingType: 'Date',
        value: value.toISOString()
      };
    }

    if (Array.isArray(value)) {
      return Promise.all(
        value.map(serializeBackupValue)
      );
    }

    if (
      value &&
      typeof value === 'object'
    ) {
      const result = {};

      for (const [key, nestedValue] of Object.entries(value)) {
        result[key] = await serializeBackupValue(
          nestedValue
        );
      }

      return result;
    }

    return value;
  }

  function dataUrlToBlob(dataUrl, fallbackType = '') {
    const parts = String(dataUrl).split(',');
    const metadata = parts[0] || '';
    const encoded = parts[1] || '';
    const match = metadata.match(/data:([^;]+)/);
    const mimeType = match ? match[1] : fallbackType;
    const binary = atob(encoded);
    const bytes = new Uint8Array(binary.length);

    for (let index = 0; index < binary.length; index++) {
      bytes[index] = binary.charCodeAt(index);
    }

    return new Blob([bytes], {
      type: mimeType || fallbackType
    });
  }

  function deserializeBackupValue(value) {
    if (Array.isArray(value)) {
      return value.map(deserializeBackupValue);
    }

    if (
      !value ||
      typeof value !== 'object'
    ) {
      return value;
    }

    if (value.__weddingType === 'Blob') {
      const blob = dataUrlToBlob(
        value.dataUrl,
        value.type
      );

      if (
        value.name &&
        typeof File !== 'undefined'
      ) {
        return new File(
          [blob],
          value.name,
          {
            type: value.type || blob.type,
            lastModified:
              Number(value.lastModified) ||
              Date.now()
          }
        );
      }

      return blob;
    }

    if (value.__weddingType === 'ArrayBuffer') {
      const binary = atob(value.base64 || '');
      const bytes = new Uint8Array(binary.length);

      for (let index = 0; index < binary.length; index++) {
        bytes[index] = binary.charCodeAt(index);
      }

      return bytes.buffer;
    }

    if (value.__weddingType === 'TypedArray') {
      const buffer = deserializeBackupValue(
        value.buffer
      );

      const Constructor =
        globalThis[value.constructor] ||
        Uint8Array;

      return new Constructor(buffer);
    }

    if (value.__weddingType === 'Date') {
      return new Date(value.value);
    }

    const result = {};

    for (const [key, nestedValue] of Object.entries(value)) {
      result[key] = deserializeBackupValue(
        nestedValue
      );
    }

    return result;
  }

  function openIndexedDatabase(name, version) {
    return new Promise((resolve, reject) => {
      const request =
        version === undefined
          ? indexedDB.open(name)
          : indexedDB.open(name, version);

      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    });
  }

  async function listWeddingDatabases() {
    if (!('indexedDB' in window)) {
      return [];
    }

    if (typeof indexedDB.databases === 'function') {
      const databases = await indexedDB.databases();

      return databases
        .map((database) => database.name)
        .filter(
          (name) =>
            typeof name === 'string' &&
            (
              name.startsWith('planificador_bodas_') ||
              name === 'AntonioEventPlannerMemory'
            )
        );
    }

    /*
      Base conocida que contiene las fotografías de invitados.
      Se usa como compatibilidad para navegadores antiguos.
    */
    return ['planificador_bodas_media_v1'];
  }

  async function exportIndexedDatabase(name) {
    let database;

    try {
      database = await openIndexedDatabase(name);
    } catch (error) {
      return null;
    }

    const databaseBackup = {
      name,
      version: database.version,
      stores: []
    };

    const storeNames = [
      ...database.objectStoreNames
    ];

    for (const storeName of storeNames) {
      const transaction = database.transaction(
        storeName,
        'readonly'
      );

      const store = transaction.objectStore(storeName);

      const values = await new Promise(
        (resolve, reject) => {
          const request = store.getAll();

          request.onsuccess = () => resolve(
            request.result || []
          );

          request.onerror = () => reject(
            request.error
          );
        }
      );

      const keys = await new Promise(
        (resolve, reject) => {
          const request = store.getAllKeys();

          request.onsuccess = () => resolve(
            request.result || []
          );

          request.onerror = () => reject(
            request.error
          );
        }
      );

      const indexes = [
        ...store.indexNames
      ].map((indexName) => {
        const index = store.index(indexName);

        return {
          name: index.name,
          keyPath: index.keyPath,
          unique: index.unique,
          multiEntry: index.multiEntry
        };
      });

      const records = [];

      for (let index = 0; index < values.length; index++) {
        records.push({
          key: await serializeBackupValue(keys[index]),
          value: await serializeBackupValue(values[index])
        });
      }

      databaseBackup.stores.push({
        name: store.name,
        keyPath: store.keyPath,
        autoIncrement: store.autoIncrement,
        indexes,
        records
      });
    }

    database.close();

    return databaseBackup;
  }

  async function collectWeddingIndexedDatabases() {
    const names = await listWeddingDatabases();
    const results = [];

    for (const name of names) {
      const database = await exportIndexedDatabase(name);

      if (
        database &&
        database.stores.some(
          (store) => store.records.length
        )
      ) {
        results.push(database);
      }
    }

    return results;
  }

  function deleteIndexedDatabase(name) {
    return new Promise((resolve, reject) => {
      const request = indexedDB.deleteDatabase(name);

      request.onsuccess = () => resolve();
      request.onerror = () => reject(request.error);

      request.onblocked = () => {
        reject(
          new Error(
            'La base de datos está siendo usada por otra ventana.'
          )
        );
      };
    });
  }

  async function restoreIndexedDatabase(databaseBackup) {
    await deleteIndexedDatabase(
      databaseBackup.name
    ).catch(() => {});

    const database = await new Promise(
      (resolve, reject) => {
        const request = indexedDB.open(
          databaseBackup.name,
          Math.max(
            1,
            Number(databaseBackup.version) || 1
          )
        );

        request.onupgradeneeded = () => {
          const database = request.result;

          databaseBackup.stores.forEach(
            (storeBackup) => {
              const options = {
                autoIncrement:
                  Boolean(storeBackup.autoIncrement)
              };

              if (
                storeBackup.keyPath !== null &&
                storeBackup.keyPath !== undefined
              ) {
                options.keyPath =
                  storeBackup.keyPath;
              }

              const store = database.createObjectStore(
                storeBackup.name,
                options
              );

              (storeBackup.indexes || []).forEach(
                (indexBackup) => {
                  store.createIndex(
                    indexBackup.name,
                    indexBackup.keyPath,
                    {
                      unique:
                        Boolean(indexBackup.unique),
                      multiEntry:
                        Boolean(indexBackup.multiEntry)
                    }
                  );
                }
              );
            }
          );
        };

        request.onsuccess = () => resolve(request.result);
        request.onerror = () => reject(request.error);
      }
    );

    for (const storeBackup of databaseBackup.stores) {
      if (!storeBackup.records.length) {
        continue;
      }

      await new Promise((resolve, reject) => {
        const transaction = database.transaction(
          storeBackup.name,
          'readwrite'
        );

        const store = transaction.objectStore(
          storeBackup.name
        );

        storeBackup.records.forEach((record) => {
          const value = deserializeBackupValue(
            record.value
          );

          if (
            store.keyPath !== null &&
            store.keyPath !== undefined
          ) {
            store.put(value);
          } else {
            store.put(
              value,
              deserializeBackupValue(record.key)
            );
          }
        });

        transaction.oncomplete = () => resolve();
        transaction.onerror = () => reject(
          transaction.error
        );
      });
    }

    database.close();
  }

  async function buildGeneralBackup() {
    return {
      type: GENERAL_BACKUP_TYPE,
      version: GENERAL_BACKUP_VERSION,
      createdAt: new Date().toISOString(),
      application: 'Planificador de bodas',
      modules: Object.keys(MODULES),
      localStorage: collectWeddingLocalStorage(),
      indexedDB:
        await collectWeddingIndexedDatabases()
    };
  }

  function backupFileName() {
    const now = new Date();

    const date = [
      now.getFullYear(),
      String(now.getMonth() + 1).padStart(2, '0'),
      String(now.getDate()).padStart(2, '0')
    ].join('-');

    const time = [
      String(now.getHours()).padStart(2, '0'),
      String(now.getMinutes()).padStart(2, '0')
    ].join('');

    return (
      'planificador_bodas_completo_' +
      date +
      '_' +
      time +
      '.json'
    );
  }

  function downloadGeneralBackup(backup) {
    const blob = new Blob(
      [JSON.stringify(backup, null, 2)],
      {
        type: 'application/json;charset=utf-8'
      }
    );

    const link = document.createElement('a');

    link.href = URL.createObjectURL(blob);
    link.download = backupFileName();

    document.body.appendChild(link);
    link.click();
    link.remove();

    window.setTimeout(() => {
      URL.revokeObjectURL(link.href);
    }, 1200);
  }

  async function saveAllModules() {
    localStorage.setItem(
      GENERAL_SAVE_KEY,
      JSON.stringify({
        version: GENERAL_BACKUP_VERSION,
        savedAt: new Date().toISOString(),
        storageKeys: Object.keys(
          collectWeddingLocalStorage()
        )
      })
    );

    showToast(
      'Todos los módulos fueron guardados.'
    );
  }

  async function exportAllModules() {
    if (generalBackupBusy) {
      return;
    }

    generalBackupBusy = true;

    showToast(
      'Preparando el respaldo completo…'
    );

    try {
      const backup = await buildGeneralBackup();

      downloadGeneralBackup(backup);

      localStorage.setItem(
        GENERAL_SAVE_KEY,
        JSON.stringify({
          version: GENERAL_BACKUP_VERSION,
          savedAt: backup.createdAt,
          storageKeys: Object.keys(
            backup.localStorage
          )
        })
      );

      showToast(
        'Respaldo completo descargado.'
      );
    } catch (error) {
      console.error(error);

      showToast(
        'No se pudo crear el respaldo completo.'
      );
    } finally {
      generalBackupBusy = false;
    }
  }

  function destroyAllModuleFrames() {
    frames.forEach((frame) => {
      frame.remove();
    });

    frames.clear();
  }

  async function importAllModules(text, fileName = '') {
    if (generalBackupBusy) {
      return;
    }

    let backup;

    try {
      backup = JSON.parse(text);
    } catch (error) {
      showToast(
        'El archivo seleccionado no contiene un JSON válido.'
      );

      return;
    }

    if (
      !backup ||
      backup.type !== GENERAL_BACKUP_TYPE ||
      !backup.localStorage
    ) {
      showToast(
        'Selecciona un respaldo completo del planificador.'
      );

      return;
    }

    const confirmed = window.confirm(
      'Se reemplazarán los datos de todos los módulos ' +
      'por el contenido de ' +
      (fileName || 'este respaldo') +
      '. ¿Deseas continuar?'
    );

    if (!confirmed) {
      return;
    }

    generalBackupBusy = true;

    showToast(
      'Restaurando todos los módulos…'
    );

    const activeModule = location.hash
      .replace(/^#/, '')
      .trim();

    try {
      destroyAllModuleFrames();

      await new Promise((resolve) => {
        window.setTimeout(resolve, 180);
      });

      clearWeddingLocalStorage();

      Object.entries(
        backup.localStorage
      ).forEach(([key, value]) => {
        if (isWeddingStorageKey(key)) {
          localStorage.setItem(
            key,
            String(value)
          );
        }
      });

      if (
        Array.isArray(backup.indexedDB) &&
        'indexedDB' in window
      ) {
        const existingNames =
          await listWeddingDatabases();

        for (const name of existingNames) {
          await deleteIndexedDatabase(name)
            .catch(() => {});
        }

        for (const databaseBackup of backup.indexedDB) {
          await restoreIndexedDatabase(
            databaseBackup
          );
        }
      }

      localStorage.setItem(
        GENERAL_SAVE_KEY,
        JSON.stringify({
          version: GENERAL_BACKUP_VERSION,
          restoredAt: new Date().toISOString(),
          sourceFile: fileName
        })
      );

      if (MODULES[activeModule]) {
        showModule(activeModule, false);
      } else {
        showHome(false);
      }

      showToast(
        'Todo el planificador fue restaurado.'
      );
    } catch (error) {
      console.error(error);

      showToast(
        'El respaldo no pudo restaurarse completamente.'
      );
    } finally {
      generalBackupBusy = false;
    }
  }

  function pad(value, size = 2) {
    return String(value).padStart(size, '0');
  }

  function updateCountdown() {
    const difference = WEDDING_DATE.getTime() - Date.now();

    if (difference <= 0) {
      document.getElementById('days').textContent = '000';
      document.getElementById('hours').textContent = '00';
      document.getElementById('minutes').textContent = '00';
      document.getElementById('seconds').textContent = '00';
      return;
    }

    const days = Math.floor(difference / 86400000);
    const hours = Math.floor((difference % 86400000) / 3600000);
    const minutes = Math.floor((difference % 3600000) / 60000);
    const seconds = Math.floor((difference % 60000) / 1000);

    document.getElementById('days').textContent = pad(days, 3);
    document.getElementById('hours').textContent = pad(hours);
    document.getElementById('minutes').textContent = pad(minutes);
    document.getElementById('seconds').textContent = pad(seconds);
  }

  function setMenu(open) {
    if (open && window.WeddingPlannerAuthGuard?.authenticated !== true) {
      open = false;
    }
    body.classList.toggle('menu-open', open);
    menuButton.setAttribute('aria-expanded', String(open));
    menuButton.setAttribute(
      'aria-label',
      open ? 'Cerrar menú' : 'Abrir menú'
    );
    drawer.setAttribute('aria-hidden', String(!open));
  }

  function closeOtherModules(activeModule) {
    modules.forEach((module) => {
      if (module === activeModule) return;

      module.classList.remove('open');
      module
        .querySelector('.module-toggle')
        .setAttribute('aria-expanded', 'false');
    });
  }

  function showToast(message) {
    toast.textContent = message;
    toast.classList.add('show');

    clearTimeout(toastTimer);

    toastTimer = setTimeout(() => {
      toast.classList.remove('show');
    }, 2600);
  }

  function decodeUtf8Base64(value) {
    const binary = atob(value);
    const bytes = new Uint8Array(binary.length);

    for (let index = 0; index < binary.length; index++) {
      bytes[index] = binary.charCodeAt(index);
    }

    return new TextDecoder('utf-8').decode(bytes);
  }


  function readSharedWeddingData() {
    try {
      const raw = localStorage.getItem(
        'planificador_bodas_datos_compartidos_v1'
      );

      return raw ? JSON.parse(raw) : null;
    } catch (error) {
      console.error(
        'No se pudo leer la información compartida.',
        error
      );

      return null;
    }
  }

  function sendSharedWeddingData(frame) {
    const payload = readSharedWeddingData();

    if (!payload || !frame?.contentWindow) {
      return;
    }

    frame.contentWindow.postMessage({
      type: 'PLANIFICADOR_BODAS_UPDATE',
      source: 'guests',
      payload
    }, '*');
  }

  function relaySharedWeddingData(
    payload,
    sourceWindow = null
  ) {
    frames.forEach((frame) => {
      if (
        !frame.contentWindow ||
        frame.contentWindow === sourceWindow
      ) {
        return;
      }

      frame.contentWindow.postMessage({
        type: 'PLANIFICADOR_BODAS_UPDATE',
        source: 'guests',
        payload
      }, '*');
    });
  }

  function createFrame(moduleKey) {
    if (frames.has(moduleKey)) {
      return frames.get(moduleKey);
    }

    const moduleData = MODULES[moduleKey];

    if (!moduleData) {
      return null;
    }

    const isDistribution =
      moduleKey === 'distribucion';

    if (!isDistribution) {
      loaderText.textContent =
        'Abriendo ' + moduleData.title + '…';

      loader.classList.add('show');
    } else {
      loader.classList.remove('show');
    }

    const frame = document.createElement('iframe');

    frame.className = 'unified-frame';
    frame.title = moduleData.title;
    frame.hidden = true;
    frame.allowFullscreen = true;
    frame.srcdoc = decodeUtf8Base64(
      moduleData.html
    );

    frame.addEventListener(
      'load',
      () => {
        if (moduleKey === 'invitados') {
          const previewEncoded =
            moduleData.previewHtml || '';

          if (previewEncoded) {
            frame.contentWindow?.postMessage({
              type:
                'PLANIFICADOR_BODAS_SET_PREVIEW_HTML',
              html: decodeUtf8Base64(
                previewEncoded
              )
            }, '*');
          }
        }

        if (isDistribution) {
          sendSharedWeddingData(frame);
        } else {
          loader.classList.remove('show');
        }
      },
      { once: true }
    );

    workspace.appendChild(frame);
    frames.set(moduleKey, frame);

    return frame;
  }

  function showModule(moduleKey, updateHash = true) {
    if (window.WeddingPlannerAuthGuard?.authenticated !== true) {
      setMenu(false);
      return;
    }

    if (!MODULES[moduleKey]) {
      showHome(updateHash);
      return;
    }

    setMenu(false);

    const activeFrame = createFrame(moduleKey);


    frames.forEach((frame, key) => {
      frame.hidden = key !== moduleKey;
    });

    if (activeFrame) {
      activeFrame.hidden = false;
    }

    body.classList.add('module-view');

    moduleQuickTabs.forEach((button) => {
      const active =
        button.dataset.quickModule === moduleKey;

      button.classList.toggle('active',active);
      button.setAttribute(
        'aria-current',
        active ? 'page' : 'false'
      );

      if (active) {
        button.scrollIntoView({
          behavior:'smooth',
          block:'nearest',
          inline:'center'
        });
      }
    });

    document.title = MODULES[moduleKey].title + ' · Planificador de bodas';

    if (updateHash && location.hash !== '#' + moduleKey) {
      history.pushState({ module: moduleKey }, '', '#' + moduleKey);
    }
  }

  function showHome(updateHash = true) {
    body.classList.remove('module-view');

    moduleQuickTabs.forEach((button) => {
      button.classList.remove('active');
      button.setAttribute('aria-current','false');
    });

    document.title = 'Planificador de bodas';

    if (updateHash && location.hash) {
      history.pushState({ module: 'home' }, '', location.pathname + location.search);
    }
  }

  function routeFromHash() {
    if (window.WeddingPlannerAuthGuard?.authenticated !== true) {
      showHome(false);
      return;
    }

    const moduleKey = location.hash.replace(/^#/, '').trim();

    if (MODULES[moduleKey]) {
      showModule(moduleKey, false);
    } else {
      showHome(false);
    }
  }

  menuButton.addEventListener('click', () => {
    if (window.WeddingPlannerAuthGuard?.authenticated !== true) {
      window.WeddingPlannerRequestAuth?.();
      return;
    }
    setMenu(!body.classList.contains('menu-open'));
  });

  backdrop.addEventListener('click', () => {
    setMenu(false);
  });

  document.addEventListener('keydown', (event) => {
    if (event.key === 'Escape') {
      if (body.classList.contains('module-view')) {
        showHome();
      } else {
        setMenu(false);
      }
    }
  });

  modules.forEach((module) => {
    const toggle = module.querySelector('.module-toggle');

    toggle.addEventListener('click', () => {
      if (window.WeddingPlannerAuthGuard?.authenticated !== true) {
        setMenu(false);
        window.WeddingPlannerRequestAuth?.();
        return;
      }
      const willOpen = !module.classList.contains('open');

      closeOtherModules(module);
      module.classList.toggle('open', willOpen);
      toggle.setAttribute('aria-expanded', String(willOpen));
    });
  });

  document.querySelectorAll('.unified-module-link').forEach((link) => {
    link.addEventListener('click', (event) => {
      event.preventDefault();
      showModule(link.dataset.module);
    });
  });

  document.querySelectorAll('.pending').forEach((link) => {
    link.addEventListener('click', (event) => {
      event.preventDefault();
      if (window.WeddingPlannerAuthGuard?.authenticated !== true) {
        setMenu(false);
        window.WeddingPlannerRequestAuth?.();
        return;
      }

      showToast(
        link.dataset.message ||
        link.dataset.name + ' estará disponible próximamente.'
      );
    });
  });

  homeButton.addEventListener('click', () => {
    showHome();
  });

  moduleQuickHome.addEventListener('click', () => {
    showHome();
  });

  moduleQuickTabs.forEach((button) => {
    button.addEventListener('click', () => {
      showModule(
        button.dataset.quickModule
      );
    });
  });

  window.addEventListener('message', (event) => {
    const message = event.data;

    if (!message || typeof message !== 'object') {
      return;
    }

    if (window.WeddingPlannerAuthGuard?.authenticated !== true) {
      return;
    }

    if (
      message.source ===
      'planificador-bodas-respaldo-general'
    ) {
      if (message.action === 'save-all') {
        saveAllModules();
      }

      if (message.action === 'export-all') {
        exportAllModules();
      }

      if (message.action === 'import-all') {
        importAllModules(
          message.text || '',
          message.fileName || ''
        );
      }

      if (message.action === 'backup-error') {
        showToast(
          message.message ||
          'No se pudo procesar el respaldo.'
        );
      }

      return;
    }

    if (
      message.source ===
      'planificador-bodas-unificado'
    ) {
      if (message.action === 'home') {
        showHome();
      }

      if (
        message.action === 'open' &&
        MODULES[message.module]
      ) {
        showModule(message.module);
      }

      return;
    }

    if (
      message.type ===
      'PLANIFICADOR_BODAS_OPEN_MODULE'
    ) {
      const moduleKey =
        message.module === 'layout'
          ? 'distribucion'
          : 'invitados';

      showModule(moduleKey);
      return;
    }

    if (
      message.type ===
        'PLANIFICADOR_BODAS_UPDATE' &&
      message.payload
    ) {
      try {
        localStorage.setItem(
          'planificador_bodas_datos_compartidos_v1',
          JSON.stringify(message.payload)
        );
      } catch (error) {
        console.error(
          'No se pudo guardar la sincronización.',
          error
        );
      }

      relaySharedWeddingData(
        message.payload,
        event.source
      );

      return;
    }

    if (
      message.type ===
        'PLANIFICADOR_BODAS_REQUEST_SYNC' ||
      message.type ===
        'PLANIFICADOR_BODAS_LAYOUT_READY'
    ) {
      const payload = readSharedWeddingData();

      if (payload && event.source) {
        event.source.postMessage({
          type: 'PLANIFICADOR_BODAS_UPDATE',
          source: 'guests',
          payload
        }, '*');
      }
    }
  });



  async function buildCloudBackup() {
    const distributionDatabase =
      await exportIndexedDatabase('AntonioEventPlannerMemory')
        .catch(() => null);

    return {
      type: 'migrandia_cloud_backup',
      version: 1,
      createdAt: new Date().toISOString(),
      localStorage: collectWeddingLocalStorage(),
      indexedDB:
        distributionDatabase &&
        distributionDatabase.stores.some((store) => store.records.length)
          ? [distributionDatabase]
          : []
    };
  }

  async function restoreCloudBackup(backup) {
    if (!backup || backup.type !== 'migrandia_cloud_backup') return;

    destroyAllModuleFrames();
    await new Promise((resolve) => window.setTimeout(resolve, 120));
    clearWeddingLocalStorage();

    Object.entries(backup.localStorage || {}).forEach(([key, value]) => {
      if (isWeddingStorageKey(key)) localStorage.setItem(key, String(value));
    });

    if (Array.isArray(backup.indexedDB)) {
      const distributionBackup = backup.indexedDB.find(
        (item) => item && item.name === 'AntonioEventPlannerMemory'
      );
      if (distributionBackup) {
        await restoreIndexedDatabase(distributionBackup).catch(console.error);
      }
    }

    applyWeddingDate(localStorage.getItem(WEDDING_DATE_STORAGE_KEY) || DEFAULT_WEDDING_DATE, false);
    showHome(false);
  }

  async function clearLocalUserData() {
    destroyAllModuleFrames();
    setMenu(false);
    showHome(false);
    clearWeddingLocalStorage();
    await deleteIndexedDatabase('AntonioEventPlannerMemory').catch(() => {});
    applyWeddingDate(DEFAULT_WEDDING_DATE, false);
  }

  window.WeddingPlannerBridge = {
    buildCloudBackup,
    restoreCloudBackup,
    clearLocalUserData,
    showToast
  };

  window.addEventListener('hashchange' , routeFromHash);
  window.addEventListener('popstate', routeFromHash);

  initializeHeroVideo();
  updateCountdown();
  setInterval(updateCountdown, 1000);
  routeFromHash();
})();
